    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] arrival = new long[m], duration = new long[m];
        for (int i = 0; i < m; i++) {
            in.nextToken(); arrival[i] = (long) in.nval;
            in.nextToken(); duration[i] = (long) in.nval;
        }
        int[] ans = assignPartners(n, arrival, duration);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i]).append(i + 1 < ans.length ? " " : "\n");
        System.out.print(sb);
    }
}
